// دالة مساعدة لتحديث صفحة تفاصيل الأداة
function updateToolDetailsLanguage() {
  const toolName = document.getElementById('detail-tool-name')?.textContent;
  if (!toolName) return;

  const tool = aiTools.find(t => t.name === toolName);
  if (!tool) return;

  // تحديث الوصف الكامل
  const fullDescription = document.getElementById('detail-tool-full-description');
  if (fullDescription) {
    fullDescription.textContent = currentLanguage === 'ar' ? (tool.desc_ar || tool.description) : tool.description;
  }

  // تحديث الوصف المختصر
  const description = document.getElementById('detail-tool-description');
  if (description) {
    description.textContent = currentLanguage === 'ar' ? (tool.desc_ar || tool.description) : tool.description;
  }

  // تحديث الأزرار
  const visitBtn = document.querySelector('#detail-tool-url');
  if (visitBtn && visitBtn.getAttribute('data-ar')) {
    visitBtn.textContent = currentLanguage === 'ar' ? visitBtn.getAttribute('data-ar') : visitBtn.getAttribute('data-en');
  }

  // تحديث العناوين
  document.querySelectorAll('[data-ar], [data-en]').forEach(element => {
    if (element.getAttribute(currentLanguage === 'ar' ? 'data-ar' : 'data-en')) {
      const text = element.getAttribute(currentLanguage === 'ar' ? 'data-ar' : 'data-en');
      if (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA') {
        element.placeholder = text;
      } else if (!element.querySelector('i') && !element.querySelector('img')) {
        element.textContent = text;
      }
    }
  });

  // تحديث عنوان الأدوات من نفس الفئة
  const sameCategoryTitle = document.getElementById('same-category-title');
  if (sameCategoryTitle && sameCategoryTitle.getAttribute('data-ar')) {
    sameCategoryTitle.textContent = currentLanguage === 'ar' ?
      sameCategoryTitle.getAttribute('data-ar') :
      sameCategoryTitle.getAttribute('data-en');
  }
}

