function toggleToolsInCategory(category, button) {
  const toolsInCategory = aiTools.filter(tool => tool.category === category);
  const categorySection = button.closest('.category-section');
  const toolsGrid = categorySection.querySelector('.row.g-4');
  const isShowingLess = button.getAttribute('data-showing-less') === 'true';

  if (isShowingLess) {
    // عرض جميع الأدوات
    toolsGrid.innerHTML = toolsInCategory.map((tool) => {
      const originalIndex = aiTools.findIndex(t => t.name === tool.name);
      const toolCard = createToolCard(tool, originalIndex);
      return toolCard.outerHTML;
    }).join('');

    // تغيير النص والأيقونة
    if (currentLang === 'en') {
      button.innerHTML = 'Show Less <i class="fas fa-chevron-up ms-2"></i>';
    } else {
      button.innerHTML = 'عرض أقل <i class="fas fa-chevron-up ms-2"></i>';
    }
    button.setAttribute('data-showing-less', 'false');
  } else {
    // عرض 6 أدوات فقط
    const toolsToShow = toolsInCategory.slice(0, 6);
    toolsGrid.innerHTML = toolsToShow.map((tool) => {
      const originalIndex = aiTools.findIndex(t => t.name === tool.name);
      const toolCard = createToolCard(tool, originalIndex);
      return toolCard.outerHTML;
    }).join('');

    // تغيير النص والأيقونة
    if (currentLang === 'en') {
      button.innerHTML = 'Show More <i class="fas fa-chevron-down ms-2"></i>';
    } else {
      button.innerHTML = 'عرض المزيد <i class="fas fa-chevron-down ms-2"></i>';
    }
    button.setAttribute('data-showing-less', 'true');
  }

  // إعادة إرفاق event listeners للأزرار الجديدة
  setTimeout(() => {
    setupToolEventListeners();
  }, 100);
}

function groupToolsByCategory() {
  const grouped = {};

  aiTools.forEach(tool => {
    if (!grouped[tool.category]) {
      grouped[tool.category] = [];
    }
    grouped[tool.category].push(tool);
  });

  return grouped;
}
