// =================================================================================
// FILTER AND CATEGORY FUNCTIONS - IMPROVED
// =================================================================================
function filterToolsByCategory(categoryName, opts = { scroll: true }) {
  console.log('🔍 Filtering tools by category:', categoryName);


  const filteredTools = aiTools.filter(tool => tool.category === categoryName);


  if (filteredTools.length === 0) {
    showToast(
      currentLang === 'en'
        ? `No tools found in category: ${categoryName}`
        : `لم يتم العثور على أدوات في الفئة: ${categoryName}`,
      'info'
    );
    return;
  }


  // الانتقال للصفحة الرئيسية
  showPage('home-page');


  // مهم: نرندر أولاً، ثم نسوي سكرول (بدون ما نرجع لأعلى)
  setTimeout(() => {
    renderFilteredTools(categoryName, filteredTools);


    if (opts.scroll) {
      requestAnimationFrame(() => {
        scrollToToolsSection();
      });
    }
  }, 50);
}

function renderFilteredTools(categoryName, filteredTools) {
  const toolsContainer = document.getElementById('featured-tools-container');
  const isArabic = currentLang === 'ar';

  toolsContainer.innerHTML = `
        <div class="row">
            <div class="col-12">
                <div class="d-flex justify-content-between align-items-center mb-4">
                    <h3 class="mb-0">
                        ${isArabic ? 'الفئة:' : 'Category:'} ${categoryName} 
                        (${filteredTools.length} ${isArabic ? 'أداة' : 'tools'})
                    </h3>
                    <button id="backToAllToolsBtn" class="btn btn-outline-secondary">
                        <i class="fas fa-arrow-left me-2"></i>
                        ${isArabic ? 'العودة لجميع الأدوات' : 'Back to All Tools'}
                    </button>
                </div>
            </div>
        </div>
        <div class="row g-4">
            ${filteredTools.map(tool => createToolCard(tool).outerHTML).join('')}
        </div>
    `;

  // إعداد event listeners
  setupFilteredToolsEvents(categoryName);
}

function setupFilteredToolsEvents(categoryName) {
  // زر الرجوع
  const backToAllToolsBtn = document.getElementById('backToAllToolsBtn');
  if (backToAllToolsBtn) {
    backToAllToolsBtn.addEventListener('click', function () {
      // إلغاء التمرير أولاً
      window.scrollTo(0, 0);
      showPage('home-page');
      setTimeout(() => {
        renderTools();
      }, 50);
    });
  }

  // التمرير النهائي بعد تحميل كل شيء
  setTimeout(() => {
    smoothScrollToTools();
  }, 100);
}

function smoothScrollToTools() {
  const featuredSection = document.getElementById('featured');
  if (featuredSection) {
    // حساب الموقع بدقة
    const elementPosition = featuredSection.getBoundingClientRect().top + window.pageYOffset;
    const offsetPosition = elementPosition - 80; // offset للهيدر

    // التمرير السلس مرة واحدة فقط
    window.scrollTo({
      top: offsetPosition,
      behavior: 'smooth'
    });

    console.log('🎯 Scrolled to tools section smoothly');
  }
}

function showAllToolsInCategory(category, button) {
  const toolsInCategory = aiTools.filter(tool => tool.category === category);

  const categorySection = button.closest('.category-section');
  const toolsGrid = categorySection.querySelector('.row.g-4');

  toolsGrid.innerHTML = toolsInCategory.map((tool) => {
    const originalIndex = aiTools.findIndex(t => t.name === tool.name);
    const toolCard = createToolCard(tool, originalIndex);
    return toolCard.outerHTML;
  }).join('');

  button.remove();
}

