function isInFooter() {
  const footerRect = footer.getBoundingClientRect();
  return footerRect.top < window.innerHeight - 100;
}

function updateButtonIcon() {
  if (isInFooter()) {
    // إذا المستخدم داخل الفوتر → ودّيه فوق
    scrollBtn.innerHTML = '<i class="bi bi-arrow-up"></i>';
  } else {
    // إذا المستخدم فوق → ودّيه للفوتر
    scrollBtn.innerHTML = '<i class="bi bi-arrow-down"></i>';
  }
}

scrollBtn.addEventListener("click", () => {
  if (isInFooter()) {
    // اطلع للهيرو
    heroSection.scrollIntoView({ behavior: "smooth" });
  } else {
    // انزل للفوتر
    footer.scrollIntoView({ behavior: "smooth" });
  }
});

window.addEventListener("scroll", updateButtonIcon);
updateButtonIcon();




