// تهيئة تحليلات الاستخدام (بدون انتهاك الخصوصية)
function initUsageAnalytics() {
  const sessionStart = new Date().toISOString();
  const sessionData = {
    startTime: sessionStart,
    theme: document.documentElement.getAttribute('data-theme'),
    language: currentLang,
    userAgent: navigator.userAgent
  };

  // تخزين محلي فقط (لا إرسال لخوادم خارجية)
  try {
    const sessions = JSON.parse(localStorage.getItem('userSessions')) || [];
    sessions.push(sessionData);
    localStorage.setItem('userSessions', JSON.stringify(sessions.slice(-50))); // حفظ آخر 50 جلسة فقط
  } catch (e) {
    console.log('📊 Analytics disabled due to privacy settings');
  }
}

// التحقق من دعم المتصفح
function checkBrowserCompatibility() {
  const features = {
    localStorage: !!window.localStorage,
    sessionStorage: !!window.sessionStorage,
    querySelector: !!document.querySelector,
    addEventListener: !!window.addEventListener,
    classList: !!document.body.classList
  };

  const unsupported = Object.keys(features).filter(key => !features[key]);

  if (unsupported.length > 0) {
    console.warn('⚠️ Unsupported features:', unsupported);
    showToast(
      currentLang === 'en'
        ? 'Some features may not work properly in your browser'
        : 'بعض الميزات قد لا تعمل بشكل صحيح في متصفحك',
      'warning'
    );
  }
}
