function enhancedInitialization() {
  console.log('🔧 Starting enhanced initialization...');

  // التحقق من توافق المتصفح
  checkBrowserCompatibility();

  // تحميل الصور المهمة مسبقاً
  preloadCriticalImages();

  // تهيئة تحليلات الاستخدام
  initUsageAnalytics();

  // إعداد مراقبة أداء الصفحة
  if ('performance' in window) {
    window.addEventListener('load', function () {
      const loadTime = performance.timing.loadEventEnd - performance.timing.navigationStart;
      console.log('⚡ Page loaded in:', loadTime, 'ms');

      if (loadTime > 3000) {
        console.warn('⚠️ Page load time is slow');
      }
    });
  }

  // إعداد خدمة العمل
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('/sw.js')
      .then(registration => {
        console.log('🔧 Service Worker registered:', registration);
      })
      .catch(error => {
        console.log('🔧 Service Worker registration failed:', error);
      });
  }
}

