// ===============================
// Unified Delegated Navbar Router
// ===============================
const PAGES = [
  'home-page',
  'news-page',
  'about-page',
  'contact-page',
  'tool-details-page'
];


function setActiveNav(linkEl) {
  document.querySelectorAll('.nav-link')
    .forEach(l => l.classList.remove('active'));
  if (linkEl) linkEl.classList.add('active');
}

// Navbar click handling
document.addEventListener('click', (e) => {
  const link = e.target.closest('.nav-link');
  if (!link) return;

  const page = link.dataset.page;
  const scrollTarget = link.dataset.scroll;

  // لو الصفحة كاملة
  if (page) {
    e.preventDefault();
    e.stopImmediatePropagation();

    showPage(page);
    setActiveNav(link);
    window.scrollTo(0, 0);


    return;
  }

  // لو سكرول داخل الرئيسية
  if (scrollTarget) {
    e.preventDefault();
    e.stopImmediatePropagation();

    showPage('home-page');
    setActiveNav(link);

    requestAnimationFrame(() => {
      const target = document.getElementById(scrollTarget);
      if (!target) return;

      const headerOffset = 90;
      const y = target.getBoundingClientRect().top + window.scrollY - headerOffset;
      window.scrollTo({ top: y, behavior: 'smooth' });
    });
    return;
  }
});
/* === FEATURE + BUGFIX PATCH === */
(function () {
  'use strict';

  /* ---------- 1) Improve Search Bar (prefix match) ---------- */
  const searchInput = document.getElementById('searchInput');
  if (searchInput && typeof window.aiTools !== 'undefined') {
    searchInput.addEventListener('input', function () {
      const q = this.value.trim().toLowerCase();
      if (!q) return;
      const results = aiTools.filter(t =>
        t.name && t.name.toLowerCase().startsWith(q)
      );
      if (typeof renderSearchResults === 'function') {
        renderSearchResults(results);
        requestAnimationFrame(scrollToToolsSection);
      }
      try { if (typeof scrollToToolsSection === 'function') scrollToToolsSection(); } catch (_) { }
      try { if (typeof smoothScrollToTools === 'function') smoothScrollToTools(); } catch (_) { }
    });
  }

  /* ---------- 2) Fix Details Button ---------- */
  document.addEventListener('click', function (e) {
    const btn = e.target.closest('.details-btn, .view-details-btn');
    if (!btn) return;
    e.preventDefault();
    e.stopImmediatePropagation();

    const toolId = btn.dataset.id;
    if (!toolId) return;

    if (typeof showToolDetails === 'function') {
      showToolDetails(toolId);
    } else if (typeof openToolDetails === 'function') {
      openToolDetails(toolId);
    }
  });

  /* ---------- 3) Fix Static Pages Overlay (About/News/etc) ---------- */
  const _origShowPage = window.showPage;
  if (typeof _origShowPage === 'function') {
    window.showPage = function (pageId) {
      document.querySelectorAll('.page').forEach(p => {
        p.style.display = 'none';
      });
      _origShowPage(pageId);
    };
  }

  console.log('✔ Search, Details button, and static pages fixed');
})();


let visibleCount = 200000;

function showMoreTools() {
  visibleCount += 20000000;
  const tools = aiTools.slice(0, visibleCount);

  const container = document.getElementById('toolsContainer');
  container.innerHTML = '';

  tools.forEach(tool => {
    container.insertAdjacentHTML('beforeend', createToolCard(tool));
  });
}


/* ===== SEARCH – FILE-AWARE FIX ===== */
(function () {
  const input = document.getElementById('searchInput');
  const container = document.getElementById('toolsContainer');
  if (!input || !container) return;

  input.addEventListener('input', function () {
    const q = this.value.trim().toLowerCase();

    // reset
    container.innerHTML = '';

    const source = q
      ? aiTools.filter(t =>
        t.name && t.name.toLowerCase().startsWith(q)
      )
      : aiTools.slice(0, 20); // default home tools

    source.forEach(tool => {
      container.insertAdjacentHTML('beforeend', createToolCard(tool));
    });
  });
})();

