/* =================================================================================
   FINAL SMART PATCH v3 (Home Details + Live Prefix Search + No Page Stacking + News)
   - Fixes: Details button failing on Home tools (missing data-tool-id)
   - Fixes: Live search results on typing (no Enter required, no forced scroll)
   - Fixes: Page stacking/overlay on back/navigation (hide all pages reliably)
   - Fixes: loadMoreTools ReferenceError (guard)
   - Restores: News link visibility + click handler safety
   NOTE: This patch is designed to run LAST.
================================================================================= */
(function () {
  'use strict';

  /* -----------------------------
     0) Helpers (safe access)
  ----------------------------- */
  function toolsArray() {
    try { return Array.isArray(aiTools) ? aiTools : []; } catch (_) { return []; }
  }
  function toolName(t) {
    return String((t && (t.name || t.title || t.tool_name || t.toolName)) || '').trim();
  }
  function toolUrl(t) {
    return String((t && (t.url || t.official_url || t.directory_url || '')) || '').trim();
  }
  function findIndex(tool) {
    const arr = toolsArray();
    if (!tool) return -1;

    // Prefer strict (name + url) match
    const n = toolName(tool).toLowerCase();
    const u = toolUrl(tool).toLowerCase();
    if (n || u) {
      const idx = arr.findIndex(x =>
        toolName(x).toLowerCase() === n &&
        toolUrl(x).toLowerCase() === u
      );
      if (idx !== -1) return idx;
    }

    // Fallback: name only
    if (n) return arr.findIndex(x => toolName(x).toLowerCase() === n);
    return -1;
  }



  /* -----------------------------
     1) Robust Page Hider (no stacking)
  ----------------------------- */
  const _origShowPage = (typeof window.showPage === 'function') ? window.showPage : null;

  function hideAllPagesHard() {
    // Hide any element that acts like a page
    document.querySelectorAll(
      '.page, .static-page, .tool-details-page, .blog-page, section[id$="-page"], [data-page].page, [data-page].static-page'
    ).forEach(el => {
      try {
        el.style.setProperty('display', 'none', 'important');
        el.classList.remove('active');
        el.setAttribute('aria-hidden', 'true');
      } catch (_) { }
    });
  }

  function showOnlyPage(pageId) {
    hideAllPagesHard();
    const target = document.getElementById(pageId);
    if (target) {
      try {
        target.style.setProperty('display', 'block', 'important');
        target.classList.add('active');
        target.setAttribute('aria-hidden', 'false');
      } catch (_) { }
    }
    try { window.scrollTo(0, 0); } catch (_) { }
  }

  if (_origShowPage) {
    // Wrap existing router but enforce hard hide first (prevents overlay)
    window.showPage = function (pageId) {
      hideAllPagesHard();
      try { _origShowPage(pageId); } catch (_) { /* fallback below */ }
      const target = document.getElementById(pageId);
      if (!target || getComputedStyle(target).display === 'none') {
        showOnlyPage(pageId);
      }
    };
  } else {
    window.showPage = showOnlyPage;
  }

  /* -----------------------------
     2) Guard undefined loadMoreTools
  ----------------------------- */
  if (typeof window.loadMoreTools !== 'function') {
    window.loadMoreTools = function () { /* no-op guard */ };
  }

  /* -----------------------------
     3) Patch createToolCard so Home cards always have a valid tool id
        (Fixes: Details not working on Home / displayToolsByCategories / performSearch)
  ----------------------------- */
  const _origCreateToolCard = (typeof window.createToolCard === 'function') ? window.createToolCard : null;

  function ensureDetailsWiring(cardEl, toolIndex) {
    if (!cardEl || cardEl.nodeType !== 1) return;

    // Standardize dataset on the card
    try { cardEl.dataset.toolId = String(toolIndex); } catch (_) { }

    // Ensure details button exists + has correct dataset + class
    const detailsBtn = cardEl.querySelector('.view-details-btn, .details-btn, [data-tool-id], [data-id]');
    if (detailsBtn) {
      try { detailsBtn.dataset.toolId = String(toolIndex); } catch (_) { }
      detailsBtn.classList.add('view-details-btn');
    }

    // If your HTML has an inline onclick that passes an object, we don't need it;
    // But we won't remove it to avoid breaking, delegation will handle it anyway.
  }

  if (_origCreateToolCard) {
    window.createToolCard = function (tool, maybeIndex) {
      const arr = toolsArray();
      let idx = (Number.isFinite(maybeIndex) ? maybeIndex : -1);
      if (idx < 0) idx = findIndex(tool);
      if (idx < 0 && arr.length) idx = arr.indexOf(tool);

      // Call original with best guess signature
      let card = null;
      try {
        card = (_origCreateToolCard.length >= 2) ? _origCreateToolCard(tool, idx) : _origCreateToolCard(tool);
      } catch (e) {
        // If original throws, fallback minimal card (keeps site alive)
        const col = document.createElement('div');
        col.className = 'col-lg-4 col-md-6';
        col.innerHTML = `
          <div class="card tool-card h-100">
            <div class="card-body d-flex flex-column">
              <h5 class="card-title">${toolName(tool) || 'Tool'}</h5>
              <div class="mt-auto" style="direction: ltr !important; text-align: left !important;">
                <button class="btn btn-outline-primary btn-sm view-details-btn" data-tool-id="${idx}">Details</button>
              </div>
            </div>
          </div>`;
        card = col;
      }

      // If the original returns HTML string, convert to element to fix datasets
      if (typeof card === 'string') {
        const wrap = document.createElement('div');
        wrap.innerHTML = card.trim();
        card = wrap.firstElementChild;
      }

      // Ensure wiring exists
      if (idx >= 0) ensureDetailsWiring(card, idx);

      return card;
    };
  }

  /* -----------------------------
     4) Smart Details handler
        - Works with: number id, string id, or object tool
  ----------------------------- */
  const _origShowToolDetails = (typeof window.showToolDetails === 'function') ? window.showToolDetails : null;

  function showToolDetailsSmart(arg) {
    const arr = toolsArray();
    if (!arr.length) return;

    let id = -1;
    if (typeof arg === 'number' && Number.isFinite(arg)) id = arg;
    else if (typeof arg === 'string' && arg.trim() !== '' && !Number.isNaN(Number(arg))) id = Number(arg);
    else if (arg && typeof arg === 'object') id = findIndex(arg);

    if (id < 0 || id >= arr.length) return;
    if (_origShowToolDetails) _origShowToolDetails(id);
  }

  try { window.showToolDetails = showToolDetailsSmart; } catch (_) { }

  // Delegated details click (survives any re-render)
  document.addEventListener('click', function (e) {
    // Add exclusions for stars, favorite, and general interactive elements so they don't jump to the details page
    if (e.target.closest('.favorite-toggle, .star-click, .visit-website-btn, a[target="_blank"]')) return;

    // Check if the element has one of the specific action classes as well
    const closestFav = e.target.closest('.favorite-toggle');
    const closestStar = e.target.closest('.star-click');
    if (closestFav || closestStar) return;

    const btn = e.target.closest('.view-details-btn, .details-btn, [data-tool-id], [data-id]');
    if (!btn) return;

    if (btn.classList.contains('favorite-toggle') || btn.classList.contains('star-click')) return;

    const raw = btn.dataset.toolId || btn.dataset.id || btn.getAttribute('data-tool-id') || btn.getAttribute('data-id');
    if (raw == null) return;

    const id = parseInt(raw, 10);
    if (Number.isNaN(id)) return;

    e.preventDefault();
    e.stopImmediatePropagation();
    showToolDetailsSmart(id);
  }, true);

  /* -----------------------------
     5) Live Prefix Search (typing shows tools immediately)
        - No Enter required
        - No forced auto-scroll
        - Does not conflict with old "Enter-only" handlers (capture + stopImmediatePropagation)
  ----------------------------- */

  (function buildSearchCache() {
    const arr = (typeof toolsArray === 'function') ? toolsArray() : (window.aiTools || []);
    if (!arr || !arr.length) return;

    // نضيف خاصية مخفية للاسم المجهز للبحث
    arr.forEach(t => {
      if (!t) return;
      if (!t.__name_lc) t.__name_lc = String(t.name || '').toLowerCase();
    });
  })();

  function scrollToToolsSection() {
    const container =
      document.getElementById('toolsContainer') ||
      document.getElementById('featured-tools-container');

    if (!container) return;

    const header =
      document.querySelector('header, .header, .navbar, .topbar');

    const offset = header ? header.offsetHeight + 10 : 10;

    const top =
      container.getBoundingClientRect().top +
      window.scrollY -
      offset;

    window.scrollTo({
      top,
      behavior: 'smooth'
    });
  }
  // function scrollToToolsSection() {
  //   const container =
  //     document.getElementById('toolsContainer') ||
  //     document.getElementById('featured-tools-container');

  //   if (!container) return;

  //   const header = document.querySelector('header, .header, .navbar, .topbar');
  //   const offset = header ? header.offsetHeight + 10 : 10;

  //   const top = container.getBoundingClientRect().top + window.scrollY - offset;

  //   window.scrollTo({ top, behavior: 'smooth' });
  // }

  const input = document.getElementById('searchInput');
  // ✅ اغلاق Overlay عند الضغط خارج
  document.addEventListener("click", (e) => {
    const overlay = document.getElementById("search-results-overlay");
    if (!overlay) return;


    if (!overlay.contains(e.target) && e.target !== input) {
      hideSearchOverlay();
    }
  });


  // ✅ اغلاق Overlay بزر Escape
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") hideSearchOverlay();
  });




  const searchBtn =
    document.getElementById('searchBtn') ||
    document.querySelector('.search-btn, #searchButton, [data-search-btn], .search-icon');

  const container =
    document.getElementById('featured-tools-container') ||
    document.getElementById('toolsContainer');

  function renderList(list) {
    if (!container) return;

    container.innerHTML = '';

    const grid = document.createElement('div');
    // اجعلها 3 أدوات في الصف (بدل 4) في عرض الأقسام
    grid.querySelectorAll('[class*="col-"]').forEach(col => {
      col.classList.remove('col-lg-3', 'col-xl-3', 'col-xxl-3');
      col.classList.add('col-lg-4', 'col-xl-4', 'col-xxl-4');
    });

    if (!list.length) {
      const no = document.createElement('div');
      no.className = 'col-12 text-center py-4 no-results';
      no.setAttribute('data-en', 'No tools start with these letters');
      no.setAttribute('data-ar', 'لا توجد أدوات تبدأ بهذه الأحرف');

      const isAr = (window.currentLang === 'ar') || (window.currentLanguage === 'ar');
      no.innerHTML = `<h4>${isAr ? 'لا توجد أدوات تبدأ بهذه الأحرف' : 'No tools start with these letters'}</h4>`;

      grid.appendChild(no);
      container.appendChild(grid);
      return;
    }

    list.forEach(tool => {

      const idx = (tool.__idx !== undefined)
        ? tool.__idx
        : (Array.isArray(window.aiTools) ? window.aiTools.indexOf(tool) : 0);

      const card = window.createToolCard(tool, idx);

      if (card && card.nodeType === 1) {
        grid.appendChild(card);
      } else if (typeof card === 'string') {
        const wrap = document.createElement('div');
        wrap.innerHTML = card.trim();
        if (wrap.firstElementChild) grid.appendChild(wrap.firstElementChild);
      }
    });

    container.appendChild(grid);
  }

  function debounce(fn, delay = 150) {
    let t;
    return function (...args) {
      clearTimeout(t);
      t = setTimeout(() => fn.apply(this, args), delay);
    };
  }

  // function runPrefixSearch() {
  //   const arr = (typeof toolsArray === 'function') ? toolsArray() : (window.aiTools || []);
  //   if (!arr || !arr.length || !input || !container) return;

  //   const q = input.value.trim().toLowerCase();
  //   let didAutoScrollForThisQuery = false;

  //   if (!q) {
  //     if (typeof window.displayToolsByCategories === 'function') {
  //       window.displayToolsByCategories();
  //     } else if (typeof window.renderTools === 'function') {
  //       window.renderTools();
  //     } else {
  //       renderList(arr.slice(0, 24));
  //     }
  //     return;
  //   }

  //   const results = arr.filter(t => (t.__name_lc || '').startsWith(q));

  //   renderList(results);

  //   // ✅ هذا هو المهم: السكّرول بعد ما يتم الرسم فعليًا
  //   requestAnimationFrame(scrollToToolsSection);
  // }

  let didAutoScrollForThisQuery = false;

  function scrollToToolsSectionSafe() {
    const toolsEl =
      document.getElementById("featured") ||
      document.getElementById("featured-tools-container") ||
      document.querySelector("#tools, #toolsSection, .tools-section");


    if (!toolsEl) return;


    const header = document.querySelector("header, .header, .navbar, .topbar");
    const offset = header ? header.offsetHeight + 10 : 10;


    // ✅ احسب المكان بالنسبة للـ Page الحقيقي
    const top = toolsEl.getBoundingClientRect().top + window.pageYOffset - offset;


    // ✅ جرّب تمرير window (الافتراضي)
    window.scrollTo({ top, behavior: "smooth" });


    // ✅ إن لم يتحرك (بعض المتصفحات في حال scroll على body)
    setTimeout(() => {
      if (window.pageYOffset === 0 && document.body.scrollTop === 0) {
        document.body.scrollTo({ top, behavior: "smooth" });
        document.documentElement.scrollTo({ top, behavior: "smooth" });
      }
    }, 50);
  }





  function getRealScrollContainer() {
    // إذا كان body هو الذي يسكرول فعليًا
    if (document.body.scrollHeight > document.body.clientHeight + 5) {
      return document.body;
    }


    // إذا html هو الذي يسكرول
    if (document.documentElement.scrollHeight > document.documentElement.clientHeight + 5) {
      return document.documentElement;
    }


    // fallback
    return window;
  }

  function normalizeSearchText(s) {
    return String(s || "")
      .toLowerCase()
      .trim()
      .replace(/\s+/g, " ")
      .replace(/[^\p{L}\p{N}\s]/gu, "");
  }

  function runPrefixSearch() {
    const arr = (typeof toolsArray === "function") ? toolsArray() : (window.aiTools || []);
    if (!arr || !arr.length || !input) return;

    const q = normalizeSearchText(input.value);

    // ✅ إذا البحث فاضي
    if (!q) {
      hideSearchOverlay();

      // رجع العرض الطبيعي للأدوات
      if (typeof window.displayToolsByCategories === "function") {
        window.displayToolsByCategories();
      } else if (typeof window.renderTools === "function") {
        window.renderTools();
      }

      return;
    }

    // ✅ Simple search - searches in name, category, and descriptions (both English and Arabic)
    const results = arr
      .map((t) => {
        const name = String(t?.name || "").toLowerCase();
        const cat = String(t?.category || "").toLowerCase();
        const descEn = String(t?.description || "").toLowerCase();
        const descAr = String(t?.desc_ar || "").toLowerCase();

        let score = 0;

        // 1) Name starts with query (best match)
        if (name.startsWith(q)) score += 100;

        // 2) Name contains query
        else if (name.includes(q)) score += 60;

        // 3) Category contains query
        if (cat.includes(q)) score += 25;

        // 4) English description contains query
        if (descEn.includes(q)) score += 10;

        // 5) Arabic description contains query
        if (descAr.includes(q)) score += 10;

        return { tool: t, score };
      })
      .filter(x => x.score > 0)
      .sort((a, b) => b.score - a.score)
      .map(x => x.tool);

    showSearchOverlay();
    renderSearchResultsOverlay(results);
  }

  if (input && container) {
    const runPrefixSearchDebounced = debounce(runPrefixSearch, 150);

    input.addEventListener('input', function (e) {
      e.stopImmediatePropagation();
      runPrefixSearchDebounced();
    }, true);

    input.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        e.preventDefault();
        e.stopImmediatePropagation();
        runPrefixSearch();
      }
    }, true);

    const form = input.closest('form');
    if (form) form.addEventListener('submit', (e) => e.preventDefault(), true);
  }

  if (searchBtn) {
    searchBtn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopImmediatePropagation();
      runPrefixSearch();
    }, true);
  }

  /* -----------------------------
     6) News link safety
        - Ensure it's visible and clickable even if other routers exist
  ----------------------------- */

  console.log('✅ FINAL SMART PATCH v3 loaded (search + details + pages + news)');
})();


/* ===== FIX: KEEP CATEGORY FILTERING + PREVENT TOP-JUMP + SCROLL AFTER RENDER ===== */
(function () {
  const categoriesGrid = document.getElementById('categories-container');
  if (!categoriesGrid) return;

  function scrollToTools() {
    const toolsEl =
      document.getElementById('toolsContainer') ||
      document.getElementById('featured-tools-container') ||
      document.querySelector('#tools, #toolsSection, .tools-section');

    if (!toolsEl) return;

    const header = document.querySelector('header, .header, .navbar, .topbar');
    const offset = header ? header.offsetHeight + 10 : 10;

    const top = toolsEl.getBoundingClientRect().top + window.scrollY - offset;
    window.scrollTo({ top, behavior: 'smooth' });
  }

  // ✅ ملاحظة: نستخدم bubble (بدون capture) عشان نخلي كودك الأصلي يشتغل
  categoriesGrid.addEventListener('click', function (e) {
    const item =
      e.target.closest('[data-category]') ||
      e.target.closest('.category-card') ||
      e.target.closest('.category-item') ||
      e.target.closest('a') ||
      e.target.closest('button');

    if (!item || !categoriesGrid.contains(item)) return;

    // ✅ امنع القفزة للأعلى فقط إذا كان رابط href="#"
    const isHashLink =
      item.tagName === 'A' &&
      (item.getAttribute('href') === '#' || item.getAttribute('href') === '');

    if (isHashLink) e.preventDefault();

    // ❌ لا تستخدم stopPropagation / stopImmediatePropagation
    // لأنها توقف كود الفلترة الأصلي

    // ✅ بعد ما كودك يفلتر ويرندر، نسوي سكّرول
    requestAnimationFrame(() => {
      requestAnimationFrame(scrollToTools);
    });
  }, false);
})();

/* ===== FORCE 3-COLUMNS (3 PER ROW) IN TOOLS RESULTS ===== */
(function () {
  function forceThreePerRow() {
    const container =
      document.getElementById('featured-tools-container') ||
      document.getElementById('toolsContainer');

    if (!container) return;

    container.querySelectorAll('.col-lg-3, .col-xl-3, .col-xxl-3').forEach(el => {
      el.classList.remove('col-lg-3', 'col-xl-3', 'col-xxl-3');
      el.classList.add('col-lg-4', 'col-xl-4', 'col-xxl-4');
    });
  }

  // ✅ بعد أي إعادة رسم كبيرة (render / filter / load more)
  const container =
    document.getElementById('featured-tools-container') ||
    document.getElementById('toolsContainer');

  if (!container) return;

  // راقب تغييرات DOM داخل الكونتينر وطبّق التعديل تلقائيًا
  const obs = new MutationObserver(() => {
    requestAnimationFrame(forceThreePerRow);
  });

  obs.observe(container, { childList: true, subtree: true });

  // تطبيق أولي
  forceThreePerRow();
})();

document.addEventListener("DOMContentLoaded", () => {
  const grid = document.getElementById("categories-container");
  if (!grid) return;


  // غيّر هذا للعنصر الذي تريد السكرول إليه (قسم الأدوات/النتائج)
  const TARGET_SELECTORS = ["#tools", "#tools-section", "#tools-container", "#all-tools", "#results"];
  const getTarget = () => {
    for (const sel of TARGET_SELECTORS) {
      const el = document.querySelector(sel);
      if (el) return el;
    }
    return null;
  };


  // Event Delegation: يلتقط الضغط سواء كان على الكرت أو أي عنصر داخله
  grid.addEventListener("click", (e) => {
    const card = e.target.closest(".category-card");
    if (!card) return;


    // مثال: جلب التصنيف من data-attribute (إذا موجود عندك)
    const category = card.dataset.category || card.getAttribute("data-category") || card.id || "";


    // استدعِ دالتك الأصلية إن كانت موجودة (اختياري)
    // مثال أسماء شائعة:
    if (typeof window.filterToolsByCategory === "function") {
      window.filterToolsByCategory(category);
    } else if (typeof window.showCategoryTools === "function") {
      window.showCategoryTools(category);
    }


    // سكرول ناعم إلى قسم الأدوات
    const target = getTarget();
    if (target) {
      target.scrollIntoView({ behavior: "smooth", block: "start" });
    } else {
      // fallback: سكرول بسيط للأسفل لو لم نجد هدف
      window.scrollTo({ top: window.scrollY + 600, behavior: "smooth" });
    }
  });
});

