function createToolCardFull(tool, index) {
  const col = document.createElement("div");
  col.className = "col-lg-4 col-md-6";
  col.dataset.toolId = index;

  if (index === undefined || index === null || Number.isNaN(Number(index))) {
    index = (window.aiTools || []).findIndex(t => t === tool);
  }

  if (index === -1 || index === undefined) index = 0;

  const isFav = isFavoriteIndex(index);

  const currentLangCode = localStorage.getItem('lang') || 'en';
  const isAr = currentLangCode === 'ar';

  const description =
    isAr
      ? (tool.desc_ar || tool.description || "")
      : (tool.description || "");

  const visitText =
    isAr
      ? "\u0632\u064a\u0627\u0631\u0629 \u0627\u0644\u0645\u0648\u0642\u0639"
      : "Visit Website";

  const detailsText =
    isAr
      ? "\u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644"
      : "Details";

  const starHtml = (typeof generateStars === 'function') ? generateStars(tool.rating || (3 + Math.random() * 2)) : '';

  col.innerHTML = `
    <div class="card tool-card card-3d tilt enhanced-card h-100">
      <div class="card-img-top position-relative" style="height: 160px; overflow: hidden; background: linear-gradient(135deg, #401F71, #BE7B72);">
        <img src="${tool.logo || ""}" alt="${tool.name || ""}"
          class="w-100 h-100 object-fit-contain p-3"
          style="object-fit: contain; background: white;"
          onerror="this.onerror=null; this.src='data:image/svg+xml;base64,'">
        <button class="btn btn-sm favorite-toggle position-absolute top-0 end-0 m-2 ${isFav ? 'active' : ''}"
                data-tool-index="${index}">
            <i class="${isFav ? 'fas' : 'far'} fa-heart" style="color: ${isFav ? '#f4cf55' : '#ffffff'}"></i>
        </button>
      </div>
      <div class="card-body d-flex flex-column">
        <div class="d-flex justify-content-between align-items-start mb-1">
          <h5 class="card-title fw-bold">${tool.name || ""}</h5>
          <span class="badge bg-secondary mb-2">${tool.category || ""}</span>
        </div>
        <div class="mb-2">${starHtml}</div>

        <p class="card-text flex-grow-1">${description}</p>

        <div class="mt-auto" style="direction: ltr !important; text-align: left !important;">
          <div style="display: flex; width: fit-content; position: relative; ">
            <button class="btn btn-primary btn-sm visit-website-btn" dir="rtl" data-url="${tool.url || "#"}" onclick="event.preventDefault(); event.stopPropagation(); var url='${(tool.url || "#").replace(/'/g, "\\'")}'; if(url && url !== '#'){ window.open(url, '_blank'); window.focus(); }">
              ${visitText}
            </button>
            <button class="btn btn-outline-primary btn-sm view-details-btn" data-tool-id="${index}">
              ${detailsText}
            </button>
          </div>
        </div>
      </div>
    </div>
  `;

  const detailsBtn = col.querySelector(".view-details-btn");
  if (detailsBtn) {
    detailsBtn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      // Generate slug from tool name and navigate to static page
      const slug = (tool.name || "")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");
      if (slug) {
        window.location.href = `/tools/${slug}.html`;
      }
    });
  }

  return col;
}

// =================================================================================
// FAVORITES - Per-Account Unified Storage
// =================================================================================

// Returns the current user's email as storage key, or 'guest' if not logged in
function _getUserKey() {
  try {
    var userData = JSON.parse(localStorage.getItem('currentUser'));
    if (userData && userData.isLoggedIn && userData.email) {
      return userData.email.toLowerCase();
    }
  } catch (e) { }
  return 'guest';
}

function getFavoritesArray() {
  var uKey = _getUserKey();
  if (!uKey) return []; // ✅ not logged in — return empty, never read shared storage
  var userKey = 'favorites_' + uKey;
  try {
    var raw = localStorage.getItem(userKey);
    var data = raw ? JSON.parse(raw) : [];
    if (Array.isArray(data)) return data;
    return [];
  } catch (e) {
    return [];
  }
}

function saveFavoritesArray(arr) {
  var uKey = _getUserKey();
  if (!uKey) return; // ✅ not logged in — never write to shared storage
  var userKey = 'favorites_' + uKey;
  localStorage.setItem(userKey, JSON.stringify(arr));
}

function isFavoriteIndex(index) {
  var favs = getFavoritesArray();
  return favs.includes(Number(index));
}

function isFavorite(tool) {
  var master = (typeof toolsArray === 'function') ? toolsArray() : (window.aiTools || []);
  var index = master.findIndex(function (t) { return t.name === tool.name || (t.id && t.id === tool.id); });
  return isFavoriteIndex(index);
}

function updateFavButtonUI(btn, isFav) {
  if (!btn) return;
  var icon = btn.querySelector("i");
  if (!icon) return;
  if (isFav) {
    btn.classList.add("active");
    icon.classList.remove("far");
    icon.classList.add("fas");
    icon.style.color = "#f4cf55ff";
  } else {
    btn.classList.remove("active");
    icon.classList.remove("fas");
    icon.classList.add("far");
    icon.style.color = "#ffffff";
  }
}

function updateFavoritesButton() {
  var favoritesBtn = document.getElementById('favoritesBtn');
  if (!favoritesBtn) return;
  try {
    var u = JSON.parse(localStorage.getItem('currentUser'));
    favoritesBtn.style.display = (u && u.isLoggedIn) ? 'inline-block' : 'none';
  } catch (e) { favoritesBtn.style.display = 'none'; }
}

window.toggleFavoriteByIndex = function (index, _btn) {
  index = Number(index);
  if (Number.isNaN(index)) return;

  var favs = getFavoritesArray();
  var exists = favs.includes(index);

  if (exists) {
    var newFavs = favs.filter(function (x) { return x !== index; });
    saveFavoritesArray(newFavs);
    document.querySelectorAll('.favorite-toggle[data-tool-index="' + index + '"], .favorite-toggle[data-tool-id="' + index + '"]').forEach(function (b) { updateFavButtonUI(b, false); });
    if (typeof showToast !== "undefined") showToast(currentLang === "ar" ? "\u062a\u0645\u062a \u0627\u0644\u0625\u0632\u0627\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0641\u0636\u0644\u0629" : "Removed from favorites", "info");
  } else {
    favs.push(index);
    saveFavoritesArray(favs);
    document.querySelectorAll('.favorite-toggle[data-tool-index="' + index + '"], .favorite-toggle[data-tool-id="' + index + '"]').forEach(function (b) { updateFavButtonUI(b, true); });
    if (typeof showToast !== "undefined") showToast(currentLang === "ar" ? "\u062a\u0645\u062a \u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0641\u0636\u0644\u0629" : "Added to favorites", "success");
  }

  updateFavoritesButton();

  if (typeof renderFavoritesModal === "function") {
    var modal = document.getElementById("favoritesModal");
    if (modal && modal.classList.contains("show")) {
      renderFavoritesModal();
    }
  }
};

window.isFavorite = isFavorite;

// Removed duplicate capture-phase favorite toggle handler

// Star click handler (capture phase)
document.addEventListener("click", function (e) {
  if (!e.target.classList.contains('star-click')) return;

  e.preventDefault();
  e.stopPropagation();

  var starVal = parseInt(e.target.dataset.star);
  var toolIdx = parseInt(e.target.dataset.toolIdx);
  if (isNaN(starVal) || isNaN(toolIdx)) return;

  // Save rating (requires login — saveUserRating is a no-op for guests)
  saveUserRating(toolIdx, starVal);

  // Update all star displays for this tool
  document.querySelectorAll('.interactive-stars[data-tool-idx="' + toolIdx + '"]').forEach(function (container) {
    var stars = container.querySelectorAll('.star-click');
    stars.forEach(function (s) {
      var sv = parseInt(s.dataset.star);
      if (sv <= starVal) {
        s.classList.remove('far');
        s.classList.add('fas');
        s.style.color = '#f4cf55';
      } else {
        s.classList.remove('fas');
        s.classList.add('far');
        s.style.color = '#ccc';
      }
    });
  });

  showToast(currentLang === 'en' ? 'Rating saved!' : '\u062a\u0645 \u062d\u0641\u0638 \u0627\u0644\u062a\u0642\u064a\u064a\u0645!', 'success');
}, true);

// ===== PATCH: Redirect Details buttons to static tool pages =====
(function () {
  document.addEventListener('click', function (e) {
    if (e.target.closest('.favorite-toggle, .star-click, .visit-website-btn')) return;
    const btn = e.target.closest('.view-details-btn');
    if (!btn) return;
    e.preventDefault();
    e.stopPropagation();
    try { e.stopImmediatePropagation(); } catch (err) { }

    // Get the tool from the card
    const card = btn.closest('.card, [data-tool-id]');
    const container = btn.closest('[data-tool-id]');

    let toolIndex = btn.dataset.toolId;
    if (!toolIndex && container) toolIndex = container.dataset.toolId;

    const tools = window.aiTools || [];
    const tool = tools[toolIndex];

    if (tool && tool.name) {
      const slug = tool.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      if (slug) {
        window.location.href = '/tools/' + slug + '.html';
        return;
      }
    }

    // Fallback: try showToolDetails
    if (typeof showToolDetails === 'function' && toolIndex) {
      showToolDetails(parseInt(toolIndex, 10));
    }
  }, true);

  console.log('✅ Static tool pages redirect enabled');
})();

// ===== AGGRESSIVE FIX: Force Details buttons to navigate to static pages =====
(function () {
  // Override at the earliest possible moment
  document.addEventListener('click', function (e) {
    if (e.target.closest('.favorite-toggle, .star-click, .visit-website-btn, a[target="_blank"]')) return;
    const btn = e.target.closest('.view-details-btn');
    if (!btn) return;

    // Stop everything else
    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    // Get tool index
    let toolIndex = btn.dataset.toolId;
    if (!toolIndex) {
      const container = btn.closest('[data-tool-id]');
      if (container) toolIndex = container.dataset.toolId;
    }

    const tools = window.aiTools || [];
    const tool = tools[parseInt(toolIndex, 10)];

    if (tool && tool.name) {
      const slug = tool.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      if (slug) {
        // Force navigation to static page
        window.location.assign('/tools/' + slug + '.html');
        return false;
      }
    }
    return false;
  }, true); // capture phase

  // Also override showToolDetails to redirect instead
  const originalShowToolDetails = window.showToolDetails;
  window.showToolDetails = function (index) {
    const tools = window.aiTools || [];
    const tool = tools[index];
    if (tool && tool.name) {
      const slug = tool.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      if (slug) {
        window.location.assign('/tools/' + slug + '.html');
        return;
      }
    }
    // Fallback to original
    if (originalShowToolDetails) originalShowToolDetails(index);
  };

  console.log('✅ Static pages redirect v2 enabled');
})();



(function () {
  'use strict';

  // ✅ Save the original showToolDetails function from main.js
  var originalShowToolDetails = window.showToolDetails;

  // ✅ Override showToolDetails to redirect to static pages
  window.showToolDetails = function (toolOrIndex) {
    console.log('✅ showToolDetails v5 intercepted:', typeof toolOrIndex);

    var tool = toolOrIndex;

    // If it's an index number, get the tool from aiTools
    if (typeof toolOrIndex === 'number') {
      tool = (window.aiTools || [])[toolOrIndex];
    }

    // If the onclick passes the entire tool object (from createToolCard)
    if (toolOrIndex && typeof toolOrIndex === 'object' && toolOrIndex.name) {
      tool = toolOrIndex;
    }

    // Navigate to static page if we have a valid tool
    if (tool && tool.name) {
      var slug = tool.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      if (slug) {
        // Close search overlay
        var overlay = document.getElementById('search-results-overlay');
        if (overlay) overlay.style.display = 'none';
        try { if (typeof hideSearchOverlay === 'function') hideSearchOverlay(); } catch (e) { }

        window.location.href = '/tools/' + slug + '.html';
        console.log('✅ Redirecting to /tools/' + slug + '.html');
        return;
      }
    }

    // Fallback to original function
    console.log('⚠️ Fallback to original showToolDetails');
    if (originalShowToolDetails) {
      originalShowToolDetails.call(window, toolOrIndex);
    }
  };

  // ✅ Handle Visit Website anchor clicks - open in background tab
  document.addEventListener('click', function (e) {
    // Find anchor with btn-primary class
    var link = e.target.closest('a.btn-primary');
    if (!link) return;

    // Must have target="_blank" attribute (indicates external link)
    if (link.getAttribute('target') !== '_blank') return;

    // Must be inside a card
    var card = link.closest('.card, .tool-card, .col-xl-4, .col-lg-6');
    if (!card) return;

    var url = link.href;
    if (!url || url === '#' || url.includes('javascript:')) return;

    // Prevent default navigation
    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    // Open in background tab
    var win = window.open(url, '_blank');
    if (win) {
      win.blur();
      window.focus();
    }
    console.log('✅ Opened in background tab:', url);
    return false;
  }, true); // capture phase

  console.log('✅ Button fix v5 loaded (AFTER main.js) - showToolDetails overridden');
})();